/* Family planning and navigation. Research records remain immutable. */
(() => {
'use strict';
window.ATLAS_EXPERIENCE_VERSION=53;
const data=window.STEM_DATA, events=data.events, schools=data.schools, profiles=data.league_guide.profiles;
const q=s=>document.querySelector(s), qa=s=>Array.from(document.querySelectorAll(s));
const safe=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const key='stemAtlasFamilyTrack.v1';
const goals={season:{name:"en la temporada",icon:'trophy',intro:"una liga principal, un mentor estable y un rol independiente del niño."},skills:{name:"profundizar en las habilidades",icon:'compass',intro:"elegir una tarea más difícil que ya se haya desarrollado, comprobar las lagunas y crear un proyecto que funcione."},camp:{name:"elegir las vacaciones",icon:'sun',intro:"el cambio específico, la edad adecuada, el lenguaje técnico y el proyecto de contenido."},school:{name:"encontrar un colegio y un equipo",icon:'book',intro:"Los puestos de ambos, el entrenador menor, el acceso al laboratorio y el costo total del año familiar."}};
const tracks={robot:{name:"Robótica",theme:['robotics'],description:"mecánica → sensores → misión autónoma",color:'orange'},ai:{name:"Programación e IA",theme:['coding','ai','games'],description:"algoritmo → datos → solución que se comprueba",color:'blue'},maker:{name:"ingeniería y su producto",theme:['technology','science','makers','robotics'],description:"problema → prototipo → prueba",color:'green'}};
const bases={nearby:{name:"Costa Rica / México",isos:['CRI','MEX'],route:'local'},latam:{name:"América Latina",isos:['CRI','MEX','BRA','ARG','CHL','COL','PER','PAN','ECU','URY','BOL','GTM','SLV','HND','NIC','DOM','CUB'],route:'southamerica'},eastasia:{name:"Japón / China / Taiwán",isos:['JPN','CHN','TWN'],route:'eastasia'},europe:{name:"Europa",isos:['CHE','ESP','FRA','DEU','NLD','BEL','ITA','PRT','GBR','IRL','DNK','SWE','NOR','FIN','AUT','POL','CZE','EST','GRC','ROU','HUN'],route:'europe'},world:{name:"Todo el mundo",isos:[],route:'destinations'}};
const regions=[['local',"Cerca de casa","Costa Rica / México",['CRI','MEX'],"la próxima temporada, las diferentes categorías de edad y la preparación del equipo.",'local'],['eastasia',"Asia oriental","Japón / China / Taiwán",['JPN','CHN','TWN'],"programas de inglés, la base de estudios y las condiciones del alojamiento.",'asia'],['europe',"tres caminos europeos","Suiza / España / Francia",['CHE','ESP','FRA'],"comparar el lenguaje del maestro, el campamento y el camino de la competencia junior.",'europe'],['southamerica',"América Latina","América del Sur",['BRA','ARG','CHL','COL','PER'],"las ligas nacionales, las vacaciones y el idioma del programa específico.",'local'],['asia-english',"Asia inglesa","Singapur / Hong Kong",['SGP','HKG'],"la escuela y el inglés técnico se comprueban por separado.",'asia'],['southeastasia',"Asia del sureste","cuatro direcciones familiares",['MYS','IDN','VNM','PHL'],"programas para pruebas cortas y caminos de equipos menores.",'asia'],['europe-north',"Europa del norte","Alemania / los Países Bajos / Bélgica",['DEU','NLD','BEL'],"las categorías escolares, el equipo local y las cuotas internacionales.",'europe'],['europe-south',"el sur de Europa","Italia / Portugal",['ITA','PRT'],"las clases diarias, las vacaciones y el idioma del curso.",'europe'],['middleeast',"Oriente Medio","Oaé / Omán / Qatar / Arabia Saudita",['ARE','OMN','QAT','SAU'],"escuelas inglesas, equipos menores y eventos tecnológicos.",'world'],['africa',"África","Seis direcciones que se vigilarán",['KEN','GHA','NGA','RWA','ZAF','MAR'],"programas y resultados de formación con una indicación precisa de la etapa.",'world']];
const focusRoutes={local:data.completeness_audit.local_focus,southamerica:data.completeness_audit.south_america_focus,eastasia:data.east_asia_focus,europe:data.europe_focus,'asia-english':data.asia_english_focus,southeastasia:data.southeast_asia_focus,'europe-north':data.north_europe_focus,'europe-south':data.south_europe_focus,middleeast:data.middleeast_focus,africa:data.africa_focus};
for(const r of regions){const f=focusRoutes[r[0]];const isos=f?.isos||f?.countries?.map(c=>c.iso);if(isos?.length)r[3]=isos;}
bases.latam.isos=data.countries.filter(c=>["América Central","América del Sur","Caribe"].includes(c.region)||c.iso==='MEX').map(c=>c.iso);
bases.europe.isos=data.countries.filter(c=>c.region.includes("Europa")).map(c=>c.iso);
bases.usa={name:"Estados Unidos",isos:['USA'],route:'strategy'};
bases.asia={name:"Asia en su totalidad",isos:data.countries.filter(c=>c.region.includes("Asia")).map(c=>c.iso),route:'destinations'};
const regionNames=Object.fromEntries(regions.map(r=>[r[0],r[2]]));regionNames.taiwan="Taiwán";
let plan={child:'both',goal:'season',track:'robot',base:'nearby',target:'',done:{}};
function validPlan(raw){const out={child:['both','mat','osc'].includes(raw?.child)?raw.child:'both',goal:Object.hasOwn(goals,raw?.goal)?raw.goal:'season',track:Object.hasOwn(tracks,raw?.track)?raw.track:'robot',base:Object.hasOwn(bases,raw?.base)?raw.base:'nearby',target:typeof raw?.target==='string'?raw.target.slice(0,200):'',done:{}};if(raw?.done&&typeof raw.done==='object')for(const [k,v]of Object.entries(raw.done)){if(/^(both|mat|osc)\|(season|skills|camp|school)\|(robot|ai|maker)\|(nearby|latam|eastasia|europe|world|usa|asia)$/.test(k)&&Array.isArray(v))out.done[k]=[...new Set(v.filter(x=>['brief','coach','gate','build','test','proof'].includes(x)))];}return out;}
try{plan=validPlan(JSON.parse(localStorage.getItem(key)||'null'));}catch{}
window.syncFamilyTrackFromURL=function(){const params=new URLSearchParams(location.search);for(const k of ['child','goal','track','base'])if(params.has(k))plan=validPlan({...plan,[k]:params.get(k)});};window.syncFamilyTrackFromURL();
const combo=()=>[plan.child,plan.goal,plan.track,plan.base].join('|');
const completed=()=>new Set(plan.done[combo()]||[]);
function persist(){try{localStorage.setItem(key,JSON.stringify(plan));}catch{notify("Los marcadores solo se guardan hasta que se cierre la página.");}const url=new URL(location.href);if(['child','goal','track','base'].some(k=>url.searchParams.has(k))){for(const k of ['child','goal','track','base'])url.searchParams.set(k,plan[k]);history.replaceState(null,'',url.toString());}}
const childName=()=>plan.child==='both'?"Matvey y Oscar":plan.child==='mat'?"Matvey":"Oscar";
const currentChildren=()=>plan.child==='both'?['mat','osc']:[plan.child];
const isNo=v=>window.STEM_FIT_TEXT.no.includes(v||'');
function matchesChild(e){return currentChildren().every(k=>!isNo(e[k]));}
function matchesBase(e){return !bases[plan.base].isos.length||e.iso.some(i=>bases[plan.base].isos.includes(i));}
const dateLabel=e=>e.start?dateText(e):e.participation==='regular'?"curso regular · el horario en la tarjeta":"el siguiente conjunto / fecha se especifica";
function candidateEvents(){const kind=plan.goal==='season'?"Competiciones":"Campamentos";return events.filter(e=>e.block===kind&&!/^P4/.test(e.priority)&&matchesChild(e)&&matchesBase(e)&&(!e.start||e.end>=TODAY)&&e.themes.some(t=>tracks[plan.track].theme.includes(t))).sort((a,b)=>score(b)-score(a)||a.title.localeCompare(b.title)).slice(0,3);}
function score(e){let v=0;if(['primary','bilingual'].includes(e.language_mode))v+=8;if(e.language_mode==='support')v+=3;if(e.evidence_level==='catalog')v-=8;if(/^P[01]/.test(e.priority))v+=5;if(e.start&&e.end>=TODAY)v+=2;if(plan.goal==='skills'&&e.participation==='regular')v+=5;if(plan.goal==='camp'&&e.participation==='regular')v-=5;if(currentChildren().every(k=>window.STEM_FIT_TEXT.journey_yes.includes(e[k]||'')))v+=3;return v;}
function candidateSchools(){return schools.filter(s=>(!bases[plan.base].isos.length||bases[plan.base].isos.includes(s.iso))&&currentChildren().every(k=>s.fit[k]==='candidate')).sort((a,b)=>Number(b.instruction_languages.includes('EN'))-Number(a.instruction_languages.includes('EN'))||a.priority-b.priority||a.id.localeCompare(b.id)).slice(0,3);}
function tasks(){const mat=plan.child!=='osc';let project=plan.track==='robot'?(mat?"Una misión autónoma con un sensor y un código propio":"un mecanismo con un sensor y un papel independiente comprensible"):plan.track==='ai'?(mat?"programa con datos, pruebas y resultado explicativo":"un juego pequeño o un algoritmo con entradas y salidas comprensibles"):(mat?"prototipo útil para un usuario concreto":"mecanismo de trabajo para tareas de la vida");
if(plan.child==='both'){const younger=plan.track==='robot'?"un mecanismo con un sensor y un papel independiente comprensible":plan.track==='ai'?"un juego pequeño o un algoritmo con entradas y salidas comprensibles":"mecanismo de trabajo para tareas de la vida";project="para Matvey — "+project+"; para Oscar — "+younger;}
const coach=plan.goal==='school'?["escuela y el tutor menor","Confirmar los lugares de ambos, las horas semanales de robótica, el entrenador y el acceso al laboratorio."]:["diagnóstico de nivel","mostrarle a su entrenador sus proyectos pasados, elegir la siguiente tarea difícil y acordar el lenguaje de las clases."];
const gate=plan.goal==='camp'?["cambio y condiciones de viaje","especificar las fechas, la edad, el idioma técnico, la recepción externa, la residencia y el lugar disponible."]:plan.goal==='school'?["la recepción y el pago completo","revisar el nivel de clase, los requisitos lingüísticos, la residencia familiar y todos los pagos obligatorios."]:["las reglas de la categoría elegida","comprobar la clase exacta, la sección de edad, la composición del equipo, el equipo y la autorización nacional."];
return[{id:'brief',title:"determinar el papel independiente",detail:plan.child==='both'?"Cada niño tiene su propia contribución y su propio nivel de tarea.":"describir lo que el niño hace y lo que quiere aprender en esta temporada.",period:"la semana 1"}, {id:'coach',title:coach[0],detail:coach[1],period:"las semanas 1–2"}, {id:'gate',title:gate[0],detail:gate[1],period:"antes de la solicitud / viaje"}, {id:'build',title:"elaborar un proyecto de trabajo",detail:"la tarea propuesta: "+project+". Conservar las versiones y explicar las decisiones tomadas.",period:"las semanas 3–6"}, {id:'test',title:"comprobar en condiciones reales",detail:"medir el resultado, registrar los fracasos y hacer una prueba de nuevo. para la temporada de equipo, un lanzamiento de prueba completo según las reglas.",period:"las semanas 7–10"}, {id:'proof',title:"fijar el resultado y el siguiente paso",detail:"código, fotografía de la construcción, un breve video, una revista de pruebas y una explicación del niño.",period:"las semanas 11–12"}];}
function leagueRoadmap(){return `<section class="ux-league-roadmap"><div class="ux-journey-heading"><div><p class="section-kicker">EDAD → CATEGORÍA → CLASIFICACIÓN</p><h3>las ligas en cada etapa</h3><p>Descubra el nivel de edad: qué hacer por tu cuenta, qué liga comprobar y qué se requiere para pasar.</p></div><button class="button secondary" data-view="leagues">Todas las ligas y reglas</button></div><div class="ux-roadmap-children">${currentChildren().map(k=>{const c=data.development_routes.children.find(x=>x.id===k);return `<article><h4>${safe(c.name)}</h4><p>${safe(c.intro)}</p><ol>${c.stages.map((step,i)=>`<li><details ${i===0?'open':''}><summary><span>${safe(step.age)} años</span><b>${safe(step.title)}</b><em>＋</em></summary><p>${safe(step.goal)}</p><div class="ux-roadmap-leagues">${step.leagues.filter(id=>profiles.some(p=>p.id===id)).map(id=>`<button data-ux-league="${safe(id)}">${safe(profiles.find(p=>p.id===id).name)} ↗</button>`).join('')}</div><p><strong>el resultado:</strong> ${safe(step.deliverable)}</p><p class="ux-roadmap-gate"><strong>el paso:</strong> ${safe(step.gate)}</p></details></li>`).join('')}</ol></article>`;}).join('')}</div></section>`;}
function blueprint(){return `<div class="motion-lab" aria-label="el camino de ingeniería interactivo"><svg class="ux-blueprint" viewBox="0 0 620 260" role="img" aria-label="El camino: idea, robot, prueba y resultado."><defs><pattern id="ux-blueprint-grid" width="24" height="24" patternUnits="userSpaceOnUse"><path d="M24 0H0V24" fill="none" stroke="#cbded8" stroke-width=".7"/></pattern><linearGradient id="ux-path-gradient"><stop stop-color="#f28b56"/><stop offset="1" stop-color="#7bb9b0"/></linearGradient></defs><rect width="620" height="260" rx="22" fill="url(#ux-blueprint-grid)"/><path class="ux-drawn-path" d="M55 175C150 175 125 66 230 66S295 183 385 183 445 79 552 79" fill="none" stroke="url(#ux-path-gradient)" stroke-width="3" stroke-dasharray="8 9"/><path class="motion-route-trace" d="M55 175C150 175 125 66 230 66S295 183 385 183 445 79 552 79" stroke-dasharray="0 1000"/><g fill="#142f3d"><circle class="motion-node active" cx="55" cy="175" r="7"/><circle class="motion-node" cx="230" cy="66" r="7"/><circle class="motion-node" cx="385" cy="183" r="7"/><circle class="motion-node" cx="552" cy="79" r="7"/></g><g class="ux-robot-drawing"><rect x="264" y="100" width="95" height="66" rx="15" fill="#fffaf0" stroke="#214b52" stroke-width="3"/><rect x="274" y="110" width="75" height="34" rx="9" fill="#dcece7"/><circle class="motion-eye" cx="294" cy="127" r="5" fill="#214b52"/><circle class="motion-eye" cx="329" cy="127" r="5" fill="#214b52"/><path d="M304 153h15M312 100V86M260 116l-20 17M364 116l20 17" fill="none" stroke="#214b52" stroke-width="3" stroke-linecap="round"/><circle cx="312" cy="83" r="5" fill="#f28b56"/><circle cx="284" cy="176" r="10" fill="#214b52"/><circle cx="340" cy="176" r="10" fill="#214b52"/></g><g font-family="system-ui,sans-serif" font-size="12" fill="#385d62"><text x="34" y="205">IDEA</text><text x="195" y="43">CREAR</text><text x="347" y="214">VERIFICAR</text><text x="506" y="55">EXPLICAR</text></g><g fill="#f28b56"><path d="m70 57 4 9 9 4-9 4-4 9-4-9-9-4 9-4Z"/><path d="m519 183 3 7 7 3-7 3-3 7-3-7-7-3 7-3Z"/></g><g class="motion-token" transform="translate(55 175)"><circle r="19"/><circle r="7"/></g></svg><div class="motion-scene-controls" role="group" aria-label="elegir la etapa del camino de ingeniería">${["Idea","la montaje","prueba","protección"].map((n,i)=>`<button data-motion-stage="${i}" aria-pressed="${i===0}">${n}</button>`).join('')}</div><div class="motion-stage-description" aria-live="polite" aria-atomic="true"><strong class="motion-stage-title">01 · idea</strong><span class="motion-stage-copy">elegir un problema y entender a quiénes sirve la solución.</span></div><div class="motion-scene-footer"><small>plan de práctica · elija el paso</small><button data-motion-play aria-pressed="false">▷ mostrar el ciclo</button></div></div>`;}
function eventChoice(e){const mode=['primary','bilingual'].includes(e.language_mode)?"El idioma del curso está confirmado":e.language_mode==='support'?"ayuda lingüística · lengua principal aclarar":"idioma y permiso  en la tarjeta";return `<article class="ux-choice"><div class="ux-choice-top"><span>${safe(e.country)}</span><span>${safe(e.block==="Competiciones"?"Temporada":"la enseñanza")}</span></div><h4>${safe(e.title)}</h4><p class="ux-choice-date">${safe(dateLabel(e))}</p><p>${safe(mode)}</p><div class="kid-chips">${currentChildren().map(k=>kidChip(e,k,k==='mat'?"Matvey":"Oscar")).join('')}</div><div class="ux-choice-actions"><button class="button secondary" data-open="${e.id}">Condiciones ↗</button><button data-favorite="${e.id}" aria-pressed="${favoriteIds.has(e.id)}" aria-label="${favoriteIds.has(e.id)?"Quitar de los planes":"en los planes"}: ${safe(e.title)}">${favoriteIds.has(e.id)?"✓ en los planes":"＋ Añadir a los planes"}</button></div></article>`;}
function schoolChoice(s){return `<article class="ux-choice"><div class="ux-choice-top"><span>${safe(s.country)}</span><span>escuela</span></div><h4>${safe(s.name)}</h4><p>${safe(s.ages)}</p><p>el idioma del paso: ${safe(s.instruction_languages.join(' / '))}. el equipo menor y el lugar para comprobar por separado.</p><button class="button secondary" data-ux-school="${s.id}">archivos y fuentes</button></article>`;}
window.renderFamilyJourney=function(){const root=q('#journey-content');if(!root)return;const done=completed(),choices=plan.goal==='school'?candidateSchools():candidateEvents();const percent=Math.round(done.size/6*100);const children=plan.child==='both'?Object.values(data.family_strategy.children):[data.family_strategy.children[plan.child]];
root.innerHTML=`<header class="ux-journey-intro"><div><p class="section-kicker">TALLER FAMILIAR</p><h3>el objetivo se convierte en<br><em>itinerario.</em></h3><p>Seleccione una tarea para Matvey, Oscar o ambas. Consigue un plan de práctica, revise las condiciones y anote sus pasos.</p><span class="ux-editorial">plan propuesto · lugares y permiso por separado</span></div>${blueprint()}</header>
<section class="ux-planner" aria-label="ajustar el track familiar"><div class="ux-planner-heading"><h3>1. ajustar la pista</h3><span>Se puede cambiar en cualquier momento.</span></div><div class="ux-child-tabs" role="group" aria-label="Para quién planificamos el itinerario">${[['both',"juntos","dos roles independientes"],['mat',"Matvey","2017 · 9 años"],['osc',"Oscar","2020 · 6 años"]].map(([id,n,age])=>`<button data-ux-child="${id}" aria-pressed="${id===plan.child}"><span>${safe(n)}</span><small>${safe(age)}</small></button>`).join('')}</div><p class="ux-control-label">el objetivo de la próxima temporada</p><div class="ux-goal-grid" role="group" aria-label="Objetivo del itinerario">${Object.entries(goals).map(([id,g])=>`<button data-ux-goal="${id}" aria-pressed="${id===plan.goal}">${icon(g.icon)}<span>${safe(g.name)}</span></button>`).join('')}</div><div class="ux-control-row"><label>Temática<select id="ux-track-select">${Object.entries(tracks).map(([id,t])=>`<option value="${id}" ${id===plan.track?'selected':''}>${safe(t.name)}</option>`).join('')}</select></label><label>donde buscar el medio ambiente<select id="ux-base-select">${Object.entries(bases).map(([id,b])=>`<option value="${id}" ${id===plan.base?'selected':''}>${safe(b.name)}</option>`).join('')}</select></label></div><label class="ux-target-label">su objetivo en una frase<input id="ux-target-input" type="text" maxlength="200" value="${safe(plan.target)}" placeholder="por ejemplo: montar un robot y pasar por la temporada local."></label></section>
<section class="ux-plan-summary ${tracks[plan.track].color}" aria-label="el recorrido elegido"><div><p class="section-kicker">${safe(childName().toUpperCase())} · ${safe(bases[plan.base].name)}</p><h3>${safe(goals[plan.goal].name)}</h3><p>${safe(goals[plan.goal].intro)}</p><span>${safe(tracks[plan.track].description)}</span></div><div class="ux-progress-ring" style="--progress:${percent*3.6}deg" role="img" aria-label="sus marcas: ${done.size} de 6 pasos"><span><b>${done.size}<small>/6</small></b><em>mis pasos</em></span></div></section>
<div class="ux-journey-heading"><div><p class="section-kicker">2. PRÁCTICA DURANTE 90 DÍAS</p><h3>de la siguiente tarea<br>a su resultado</h3><p>Tempo  Proposición para la familia. La marca significa tu evaluación de la ejecución del paso.</p></div><button class="text-button" data-ux-reset-steps>dejar de marcar</button></div><div class="ux-task-grid">${tasks().map((t,i)=>`<article class="ux-task ${done.has(t.id)?'done':''}"><div class="ux-task-meta"><span>0${i+1}</span><small>${safe(t.period)}</small></div><h4>${safe(t.title)}</h4><p>${safe(t.detail)}</p><label><input type="checkbox" data-ux-task="${t.id}" aria-label="Marcar paso: ${safe(t.title)}" ${done.has(t.id)?'checked':''}><span>${done.has(t.id)?"lo señalado por mí":"para celebrar su paso"}</span></label></article>`).join('')}</div>
<section class="ux-child-notes" aria-label="el papel de cada niño">${children.map(c=>`<article><span class="ux-child-avatar ${c.birth_year===2017?'mat':'osc'}">${safe(c.name.slice(0,1))}</span><div><h4>${safe(c.name)} · un papel independiente</h4><p>${safe(c.detail)}</p><details><summary>¿Qué es el resultado de la temporada?</summary><p>${safe(c.proof)}</p></details></div></article>`).join('')}</section>
<div class="ux-journey-heading"><div><p class="section-kicker">3. ENTORNO PARA ESTE ITINERARIO</p><h3>tarjetas con las que comenzar la verificación</h3><p>Selección editorial por territorio, restricciones de edad y pruebas lingüísticas. la nueva solicitud aún no ha sido aceptada.</p></div><button class="button secondary" data-ux-find>todas las opciones</button></div><div class="ux-choice-grid">${choices.length?choices.map(x=>plan.goal==='school'?schoolChoice(x):eventChoice(x)).join(''):`<div class="ux-no-choice"><h4>No hay combinación exacta.</h4><p>Extendiendo la región o abriendo todas las opciones.</p><button class="button secondary" data-ux-find>abrir el catálogo</button></div>`}</div>
<section class="ux-horizon"><div><p class="section-kicker">4. HORIZONTE DE DESARROLLO</p><h3>la próxima temporada<br>parte de un camino más largo.</h3><p>plan de habilidades para 10–12 años. categorías de edad, el equipo, Selección y fechas futuras se revisan cada temporada.</p></div><ol>${[['2026–2028',"su papel y equipo regular","la autoconstrucción, el código, las pruebas y la explicación de la solución."],['2028–2031',"profundidad de ingeniería","Los sensores, CAD, electrónica, Python / C++. el comando de hermanos  si se permiten las reglas."],['2031–2034',"un equipo fuerte y tareas reales","una liga más compleja en edad, un laboratorio y un proyecto con un usuario real."],['2034–2038',"especialización y su producto","Profundizar en el interés, comprobar la demanda y recopilar una cartera de soluciones."]].map(([period,title,detail],i)=>`<li><span>0${i+1}</span><div><small>${period}</small><h4>${title}</h4><p>${detail}</p></div></li>`).join('')}</ol></section>
${leagueRoadmap()}
${window.nearbyParticipationMarkup?.()||''}
<section class="ux-plan-tools"><div><h3>seguir juntos</h3><p>las marcas y las selecciones se guardan en este navegador. el archivo del plan las transfiere al dispositivo de la esposa; la referencia solo transfiere las configuraciones de la pista.</p></div><div><button class="button primary" data-ux-export>descargar el plan</button><button class="button secondary" data-ux-import>abrir el archivo del plan</button><button class="button secondary" data-ux-share>enlace a esta pista</button><button class="button secondary" data-ux-route="${bases[plan.base].route}">Guía de dirección</button><input id="ux-plan-file" type="file" accept="application/json,.json" hidden></div></section>`;
};
window.renderAtlasDestinations=function(){q('#destinations-content').innerHTML=`<header class="ux-destinations-head"><div><p class="section-kicker">PAÍSES · UN OBJETIVO EN CADA UNO</p><h3>Comienza por aquí.<br><em>crecer en todo el mundo.</em></h3><p>Seleccione la dirección: dentro de  edad, idioma, entorno escolar, campamento y camino a la competición.</p></div><div class="ux-coverage-orb"><b>${data.coverage_summary.countries_with_records}</b><span>de los países y territorios<br>con registros concretos</span><small>de ${data.coverage_summary.countries} · un alcance parcial</small></div></header><div class="ux-region-grid">${regions.map(([route,kicker,name,isos,description,tone],i)=>{const n=events.filter(e=>e.iso.some(x=>isos.includes(x))).length,ns=schools.filter(s=>isos.includes(s.iso)).length;return `<article class="ux-region-card ${tone}"><div class="ux-region-art"><svg viewBox="0 0 260 110" aria-hidden="true"><path d="M10 90Q60 15 110 60T250 25" fill="none" stroke="currentColor" stroke-width="2" stroke-dasharray="5 7"/><circle cx="45" cy="56" r="17" fill="currentColor" opacity=".12"/><circle cx="45" cy="56" r="4" fill="currentColor"/><circle cx="151" cy="71" r="25" fill="currentColor" opacity=".12"/><circle cx="151" cy="71" r="5" fill="currentColor"/><circle cx="222" cy="40" r="4" fill="currentColor"/></svg><span>${String(i+1).padStart(2,'0')}</span></div><div><p class="section-kicker">${safe(kicker)}</p><h4>${safe(name)}</h4><p>${safe(description)}</p><p class="ux-region-countries">${isos.map(countryName).map(safe).join(' · ')}</p><div class="ux-region-counts"><span>${n} fichas</span><span>${ns} de los expedientes escolares</span></div><button class="button secondary" data-ux-route="${route}">abrir el rumbo</button></div></article>`}).join('')}</div><div class="ux-destinations-footer"><p>Los números muestran los registros de esta base de datos. La auditoría local completa de todos los países todavía está en curso.</p><button class="button secondary" data-view="map">abrir un mapa del mundo</button><button class="button secondary" data-view="about">fuentes y alcance</button></div>`;};
function renderHome(){const due=events.filter(e=>/^P[01]/.test(e.priority)&&e.deadline>=TODAY&&e.deadline<=addDays(TODAY,30)&&!/^P4/.test(e.priority)).sort((a,b)=>a.deadline.localeCompare(b.deadline)).slice(0,3);q('#ux-home').innerHTML=`<div class="ux-start-heading"><p class="section-kicker">NO TE PIERDAS TU TEMPORADA</p><h2>¿Por dónde empezamos?</h2><span>${events.length.toLocaleString('es')} fichas · ${schools.length} colegios · ${profiles.length} perfiles</span></div><div class="ux-start-grid">${[['journey','arrow',"Preparar itinerario","objetivo y práctica para cada niño",'orange'],['catalog','trophy',"encontrar una competencia","edad, categoría, equipo y selección",'blue'],['camps','sun',"planificar las vacaciones","Idioma, proyecto, sesión y alojamiento",'green'],['schools','book',"Seleccionar el medio","escuela, tutor y laboratorio",'navy']].map(([view,ic,title,detail,tone])=>`<button class="ux-start-card ${tone}" data-view="${view}">${icon(ic)}<b>${title}</b><span>${detail}</span><em>↗</em></button>`).join('')}</div>${due.length?`<section class="ux-horizon-soon"><div><p class="section-kicker">PRÓXIMOS PLAZOS</p><h3>Comprobar primero<br>estas fechas.</h3><button class="text-button" data-view="calendar">Todo el calendario</button></div><div class="ux-due-list">${due.map(e=>`<button data-open="${e.id}"><span>${shortDate(e.deadline)}</span><div><b>${safe(e.title)}</b><small>${safe(e.country)} · el plazo de solicitud / verificación</small></div><em>↗</em></button>`).join('')}</div></section>`:''}`;}
function effectiveRoute(){const h=location.hash.slice(1);return regionNames[h]?h:state.view;}
window.refreshAtlasUX=function(){const r=effectiveRoute(),regional=!!regionNames[r];document.body.dataset.uxView=r;document.body.classList.toggle('ux-regional',regional);document.body.classList.add('ux-ready');q('#ux-home').hidden=state.view!=='explore';if(state.view==='explore')renderHome();if(regional){q('#view-label').textContent=regionNames[r];q('#section-title').textContent=regionNames[r];q('#section-kicker').textContent="ITINERARIO REGIONAL";let bar=q('#ux-region-jumps');if(!bar){bar=document.createElement('nav');bar.id='ux-region-jumps';bar.className='ux-region-jumps';bar.setAttribute('aria-label',"las secciones del recorrido regional");q('#audit-body').before(bar);}bar.innerHTML=`<button data-ux-route="destinations">← Direcciones</button>${[['.taiwan-intro',"resumen"],['.europe-probe',"el objetivo del viaje"],['.europe-family-picks',"Por dónde empezar"],['.europe-routes',"de los países y condiciones"],['.europe-plan',"los siguientes pasos"]].filter(([sel])=>q('#audit-body '+sel)).map(([sel,name])=>`<button data-ux-scroll="${sel}">${name}</button>`).join('')}`;}else q('#ux-region-jumps')?.remove();qa('#navigation .nav-item,#ux-mobile-nav [data-view]').forEach(b=>{const active=b.dataset.view===r||b.dataset.uxRoute===r;b.classList.toggle('active',active);if(active)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});if(regional)q('.nav-regions').open=true;q('.category-row').hidden=state.view!=='explore';q('.best-entry').hidden=state.view!=='explore';q('.school-home-link').hidden=state.view!=='explore';q('.ux-sidebar-shade').hidden=!q('.sidebar').classList.contains('open');q('[data-ux-back-top]').hidden=window.scrollY<900;icons();};
document.addEventListener('stem:render',window.refreshAtlasUX);
function closeDrawer(){q('.sidebar').classList.remove('open');q('.page-shell').inert=false;document.body.classList.remove('ux-menu-open');q('#menu-button').setAttribute('aria-expanded','false');q('.ux-sidebar-shade').hidden=true;requestAnimationFrame(()=>q('#menu-button').focus({preventScroll:true}));}
function motion(){return matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth';}
function scrollView(){requestAnimationFrame(()=>{const el=state.view==='explore'?q('#hero'):q('.workspace');el.scrollIntoView({behavior:motion(),block:'start'});q('#section-title').tabIndex=-1;if(state.view!=='explore')q('#section-title').focus({preventScroll:true});});}
function navigate(route){if(regionNames[route]){if(location.hash!=='#'+route)history.pushState(null,'','#'+route);applyLocationRoute();q('.sidebar').classList.remove('open');q('#menu-button').setAttribute('aria-expanded','false');q('.ux-sidebar-shade').hidden=true;}else setView(route);scrollView();}
function findAll(){if(plan.goal==='school'){navigate('schools');window.focusAtlasSchools(bases[plan.base].isos,bases[plan.base].name,plan.child);return;}navigate('catalog');Object.assign(state,{best:false,league:'',block:plan.goal==='season'?"Competiciones":"Campamentos",routeIsos:[...bases[plan.base].isos],country:'',region:'',kid:plan.child==='both'?'':plan.child,query:'',theme:plan.track==='robot'?'robotics':plan.track==='ai'?'coding':'',language:'',languageMode:'',scope:'',participation:'',admission:'',evidence:'',dates:'',priority:false,excluded:true,limit:12});render();}
function openSchool(id){window.openAtlasSchool(id);}
function downloadJSON(){const payload={app:'STEM Atlas family plan',version:1,exported_at:new Date().toISOString(),research_asof:data.asof,plan:validPlan(plan),favorite_ids:Array.from(favoriteIds),note:"No se confirma el registro, el pago, el lugar de la escuela o el premio."};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='STEM_family_plan.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);}
async function importJSON(file){try{if(!file||file.size>512000)throw Error();const raw=JSON.parse(await file.text());if(raw.app!=='STEM Atlas family plan'||raw.version!==1||!raw.plan)throw Error();plan=validPlan(raw.plan);if(Array.isArray(raw.favorite_ids))raw.favorite_ids.filter(id=>events.some(e=>e.id===id)).forEach(id=>favoriteIds.add(id));persist();try{localStorage.setItem('stemAtlasFavorites.v1',JSON.stringify([...favoriteIds]));}catch{}render();notify("El plan se ha trasladado. El plan elegido se ha guardado.");}catch{notify("No se puede abrir el plan. Seleccione el archivo JSON descargado de este atlas.");}}
function shareTrack(){const url=new URL(location.href);url.search='';url.hash='journey';for(const k of ['child','goal','track','base'])url.searchParams.set(k,plan[k]);history.replaceState(null,'',url.toString());const payload=url.toString();if(navigator.clipboard?.writeText)navigator.clipboard.writeText(payload).then(()=>notify("La referencia está copiada. Transmite las configuraciones sin marcas personales.")).catch(()=>showShareURL(payload));else showShareURL(payload);}
function showShareURL(url){const tools=q('.ux-plan-tools');let box=q('#ux-share-url');if(!box){box=document.createElement('input');box.id='ux-share-url';box.readOnly=true;box.setAttribute('aria-label',"enlace a la pista seleccionada");tools.append(box);}box.value=url;box.focus();box.select();notify("Copie el enlace que se ha asignado.");}
let searchType='all',searchIndex=-1,lastSearchFocus;
const normalize=s=>String(s).toLocaleLowerCase('es').normalize('NFD').replace(/[\u0300-\u036f]/g,'');
const index=[...events.map(e=>({id:e.id,type:e.block==="Competiciones"?'competition':e.block==="Campamentos"?'camp':'event',title:e.title,detail:e.country+' · '+(e.city||e.age),search:normalize([e.id,e.title,e.country,e.city,e.age,e.themes.map(t=>({robotics:"robótica robot",ai:"IA AI",coding:"código de programación",technology:"tecnología STEM",science:"Ciencia"}[t]||t))].join(' '))})),...schools.map(s=>({id:s.id,type:'school',title:s.name,detail:s.country+' · '+s.ages,search:normalize([s.id,s.name,s.country,s.city,s.curriculum].join(' '))})),...profiles.map(p=>({id:p.id,type:'league',title:p.name,detail:p.age_summary,search:normalize([p.id,p.name,p.summary,p.age_summary].join(' '))}))];
const searchTypeNames={all:"Todo",competition:"Competiciones",camp:"Campamentos",school:"escuelas",league:"las ligas",event:"Exposiciones"};
function searchResults(){const text=normalize(q('#ux-search-input').value.trim()),tokens=text.split(/\s+/).filter(Boolean);const result=index.filter(x=>(searchType==='all'||x.type===searchType)&&tokens.every(t=>x.search.includes(t))).sort((a,b)=>Number(b.title.toLocaleLowerCase().startsWith(text))-Number(a.title.toLocaleLowerCase().startsWith(text)));const rows=result.slice(0,text?14:6);searchIndex=-1;q('#ux-search-types').innerHTML=Object.entries(searchTypeNames).map(([id,name])=>`<button data-ux-search-type="${id}" aria-pressed="${id===searchType}">${name}</button>`).join('');q('#ux-search-count').textContent=text?`${result.length} coincidencias · mostrado ${rows.length}`:"comience a escribir el nombre, país o tema";q('#ux-search-results').innerHTML=(!text&&searchType==='all'?`<div class="ux-search-quick">${[['journey',"Mi itinerario"],['destinations',"Temáticas"],['calendar',"Calendario"],['saved',"Nuestros planes"]].map(([route,name])=>`<button data-ux-search-route="${route}">${name} ↗</button>`).join('')}</div>`:'')+(rows.length?rows.map(x=>`<button class="ux-search-result" data-ux-result="${safe(x.id)}" data-ux-result-type="${x.type}"><span class="ux-search-type ${x.type}">${searchTypeNames[x.type]}</span><div><b>${safe(x.title)}</b><small>${safe(x.detail)}</small></div><em>↗</em></button>`).join(''):"<p class=\"ux-search-empty\">No hay coincidencias. Prueba el país o el nombre de la liga.</p>");}
function openSearch(){lastSearchFocus=document.activeElement;q('#ux-search-dialog').showModal();q('#ux-search-input').value='';searchType='all';searchResults();q('#ux-search-input').focus();}
function closeSearch(){q('#ux-search-dialog').close();lastSearchFocus?.focus({preventScroll:true});}
function openLeague(id){if(!profiles.some(p=>p.id===id))return;Object.assign(leagueState,{tab:'guide',best:false,query:'',group:'',age:''});leagueState.opened.add(id);navigate('leagues');const el=q('#league-'+id);if(el){el.querySelector('details').open=true;el.scrollIntoView({behavior:motion(),block:'start'});el.querySelector('summary')?.focus({preventScroll:true});}}
function searchOpen(id,type){closeSearch();if(type==='school')openSchool(id);else if(type==='league')openLeague(id);else openEvent(id);}
document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;if(b.dataset.view)requestAnimationFrame(()=>{scrollView();window.refreshAtlasUX();});if(b.dataset.uxRoute)navigate(b.dataset.uxRoute);if(b.dataset.uxSchool)openSchool(b.dataset.uxSchool);if(b.dataset.uxLeague)openLeague(b.dataset.uxLeague);if(b.dataset.uxScroll)q('#audit-body '+b.dataset.uxScroll)?.scrollIntoView({behavior:motion(),block:'start'});if(b.hasAttribute('data-ux-find'))findAll();if(b.dataset.uxChild){plan.child=b.dataset.uxChild;persist();renderFamilyJourney();q(`[data-ux-child="${plan.child}"]`)?.focus({preventScroll:true});}if(b.dataset.uxGoal){plan.goal=b.dataset.uxGoal;persist();renderFamilyJourney();q(`[data-ux-goal="${plan.goal}"]`)?.focus({preventScroll:true});}if(b.hasAttribute('data-ux-reset-steps')){plan.done[combo()]=[];persist();renderFamilyJourney();q('[data-ux-reset-steps]')?.focus({preventScroll:true});}if(b.hasAttribute('data-ux-export'))downloadJSON();if(b.hasAttribute('data-ux-import'))q('#ux-plan-file').click();if(b.hasAttribute('data-ux-share'))shareTrack();if(b.hasAttribute('data-ux-search'))openSearch();if(b.hasAttribute('data-ux-search-close'))closeSearch();if(b.dataset.uxResult)searchOpen(b.dataset.uxResult,b.dataset.uxResultType);if(b.dataset.uxSearchRoute){closeSearch();navigate(b.dataset.uxSearchRoute);}if(b.dataset.uxSearchType){searchType=b.dataset.uxSearchType;searchResults();q(`[data-ux-search-type="${searchType}"]`).focus();}if(b.hasAttribute('data-ux-menu')){q('#menu-button').click();q('.ux-sidebar-shade').hidden=!q('.sidebar').classList.contains('open');}if(b.id==='menu-button')q('.ux-sidebar-shade').hidden=!q('.sidebar').classList.contains('open');if(b.hasAttribute('data-ux-close-menu'))closeDrawer();if(b.hasAttribute('data-ux-back-top'))scrollView();if(b.dataset.auditTab){const route=regionNames[b.dataset.auditTab]?b.dataset.auditTab:'about';if(location.hash!=='#'+route)history.pushState(null,'','#'+route);window.refreshAtlasUX();}});
document.addEventListener('change',e=>{const t=e.target;if(t.dataset.uxTask){const done=completed();t.checked?done.add(t.dataset.uxTask):done.delete(t.dataset.uxTask);plan.done[combo()]=[...done];persist();const id=t.dataset.uxTask;renderFamilyJourney();q(`[data-ux-task="${id}"]`)?.focus({preventScroll:true});}if(t.id==='ux-track-select'||t.id==='ux-base-select'){plan[t.id==='ux-track-select'?'track':'base']=t.value;persist();renderFamilyJourney();q('#'+t.id)?.focus({preventScroll:true});}if(t.id==='ux-plan-file')importJSON(t.files?.[0]);});
document.addEventListener('input',e=>{if(e.target.id==='ux-target-input'){plan.target=e.target.value.slice(0,200);persist();}if(e.target.id==='ux-search-input')searchResults();});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();q('#ux-search-dialog').open?closeSearch():openSearch();}if(e.key==='Tab'&&q('.sidebar').classList.contains('open')&&matchMedia('(max-width:720px)').matches){const nodes=qa('.sidebar a,.sidebar button,.sidebar summary').filter(el=>el.getClientRects().length);const first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}if(e.key==='Escape'&&q('.sidebar').classList.contains('open'))closeDrawer();if(q('#ux-search-dialog').open&&['ArrowDown','ArrowUp','Enter'].includes(e.key)&&(document.activeElement.id==='ux-search-input'||document.activeElement.matches('.ux-search-result'))){const rows=qa('.ux-search-result');if(!rows.length)return;e.preventDefault();if(e.key==='Enter'){if(searchIndex>=0)rows[searchIndex].click();else rows[0].click();return;}searchIndex=(searchIndex+(e.key==='ArrowDown'?1:-1)+rows.length)%rows.length;rows.forEach((r,i)=>r.classList.toggle('selected',i===searchIndex));rows[searchIndex].focus({preventScroll:true});rows[searchIndex].scrollIntoView({block:'nearest'});}});
q('.ux-sidebar-shade')?.addEventListener('click',closeDrawer);
q('#ux-search-dialog')?.addEventListener('click',e=>{if(e.target===q('#ux-search-dialog'))closeSearch();});
q('#ux-search-dialog')?.addEventListener('cancel',()=>lastSearchFocus?.focus({preventScroll:true}));
window.addEventListener('resize',()=>{if(innerWidth>720&&q('.sidebar').classList.contains('open'))closeDrawer();});
window.addEventListener('scroll',()=>{q('[data-ux-back-top]').hidden=window.scrollY<900;},{passive:true});
new MutationObserver(()=>{const on=q('.sidebar').classList.contains('open')&&matchMedia('(max-width:720px)').matches;q('.ux-sidebar-shade').hidden=!on;q('.page-shell').inert=on;document.body.classList.toggle('ux-menu-open',on);if(on)q('.sidebar [data-ux-close-menu]')?.focus();}).observe(q('.sidebar'),{attributes:true,attributeFilter:['class']});
})();
